package com.sentinelai.incidents.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="incident_timeline") public class IncidentTimeline { @Id private UUID id; private UUID incidentId; private String tenantId; private String action; private String actor; private String details; private Instant createdAt; protected IncidentTimeline(){} public IncidentTimeline(UUID id,UUID incidentId,String tenantId,String action,String actor,String details){this.id=id;this.incidentId=incidentId;this.tenantId=tenantId;this.action=action;this.actor=actor;this.details=details;this.createdAt=Instant.now();} public UUID getId(){return id;} public UUID getIncidentId(){return incidentId;} public String getTenantId(){return tenantId;} public String getAction(){return action;} public String getActor(){return actor;} public String getDetails(){return details;} public Instant getCreatedAt(){return createdAt;} }
